<script setup>
import AppShell from '../../Components/Ui/AppShell.vue'
import de from '../../i18n/de'
import { router, useForm } from '@inertiajs/vue3'
import { computed, ref } from 'vue'

const props = defineProps({ group: Object, workspace: Object, groupOptions: Array, holidayPeriods: Array, canUndoReflow: Boolean })
const curriculumOpen = ref(true)
const expandedUnits = ref([])
const editorLesson = ref(null)
const editorUnit = ref(null)
const phaseEditor = ref(null)
const newUnitOpen = ref(false)
const dragOverSlot = ref(null)
const dropPreviewSlots = ref([])
const dropInsertSlots = ref([])
const dropInvalidSlot = ref(null)
const dropOverflow = ref(0)
const dragOverLessonId = ref(null)
const curriculumDropActive = ref(false)
const draggingCurriculum = ref(false)
const draggingScheduledItem = ref(false)
const unscheduleDropActive = ref(false)
const slotMenu = ref(null)
const decisionDialog = ref(null)
const dragOverUnitId = ref(null)
const dragOverUnitPosition = ref(null)
const autoPlanDialog = ref(false)
const newUnit = useForm({ title: '', notes: '' })
const unitEditor = useForm({ title: '', notes: '' })
const autoPlanForm = useForm({ start_mode: 'free', schedule_slot_id: null, keep_together: true })
const slotsByDate = computed(() => props.workspace.slots.reduce((groups, slot) => { (groups[slot.date] ||= []).push(slot); return groups }, {}))
const groupGrades = computed(() => (props.group.grade_levels ?? []).map(level => String(level.grade_level ?? level).match(/\d+/)?.[0]).filter(Boolean))
const curricula = computed(() => props.workspace.curricula.flatMap(curriculum => curriculum.versions.flatMap(version => version.topics.filter(topic => groupGrades.value.includes(String(topic.year))).map(topic => ({ ...topic, curriculum_title: curriculum.title })))))
const coveragePercent = computed(() => { const total = Number(props.workspace.coverage?.curriculum_total ?? 0); return total ? Math.round((Number(props.workspace.coverage?.curriculum_covered ?? 0) / total) * 100) : 0 })
const holidays = computed(() => (props.holidayPeriods ?? []).map(holiday => ({ ...holiday, starts_on: String(holiday.starts_on).slice(0, 10), ends_on: String(holiday.ends_on).slice(0, 10) })))
const planningEntries = computed(() => [...Object.entries(slotsByDate.value).map(([date, slots]) => ({ type: 'day', date, slots })), ...holidays.value.map(holiday => ({ type: 'holiday', date: holiday.starts_on, holiday }))].sort((left, right) => left.date.localeCompare(right.date) || (left.type === 'holiday' ? -1 : 1)))
const autoPlanSlots = computed(() => props.workspace.slots.filter(slot => slot.status === 'free' && !slot.scheduled_lesson && !slot.is_pinned))
const isExpanded = unit => expandedUnits.value.includes(unit.id)
const toggleUnit = unit => { expandedUnits.value = isExpanded(unit) ? expandedUnits.value.filter(id => id !== unit.id) : [...expandedUnits.value, unit.id] }
const unitTone = unit => unit?.id ? `unit-tone-${Math.abs(Number(unit.id)) % 6}` : ''
const lessonIsPlanned = lesson => (lesson.scheduled_lessons?.length ?? 0) > 0
const unitPlanState = unit => { const planned = unit.lessons.filter(lessonIsPlanned).length; return planned === 0 ? 'not-planned' : planned === unit.lessons.length ? 'planned' : 'partial' }
const planStateLabel = state => ({ planned: de.planned, partial: de.partiallyPlanned, 'not-planned': de.notPlanned }[state])
const statusClass = slot => ({ free: 'text-bg-light', buffer: 'text-bg-info', absent: 'text-bg-danger', cancelled: 'text-bg-warning', blocked: 'text-bg-secondary' }[slot.status] ?? 'text-bg-light')
const statusLabel = slot => ({ free: de.available, buffer: de.buffer, absent: de.absent, cancelled: de.cancelled, blocked: de.blocked }[slot.status] ?? slot.status)
const slotStatusOptions = [{ value: 'free', label: de.available }, { value: 'buffer', label: de.buffer }, { value: 'absent', label: de.absent }, { value: 'cancelled', label: de.cancelled }, { value: 'blocked', label: de.blocked }]
const formatDate = value => { const dateValue = String(value ?? ''); const date = /^\d{4}-\d{2}-\d{2}$/.test(dateValue) ? new Date(`${dateValue}T12:00:00`) : new Date(dateValue); return Number.isNaN(date.getTime()) ? dateValue : date.toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' }) }
const competencyText = competency => { const curriculum = competency.curriculum_competency; const number = competency.external_identifier || competency.number || competency.education_plan_competency?.external_identifier || competency.education_plan_competency?.number || curriculum?.external_identifier; const text = competency.local_wording || competency.education_plan_competency?.text || competency.text || competency.raw_text || (competency.display && competency.display !== number ? competency.display : null) || curriculum?.text || curriculum?.raw_text || (curriculum?.display && curriculum.display !== number ? curriculum.display : null) || de.noCompetencyText; return number ? `${number} – ${text}` : text }
function take(topic) { router.post(`/jahresplanung/${props.group.id}/curriculum-themen/${topic.id}/uebernehmen`) }
function createUnit() { newUnit.post(`/jahresplanung/${props.group.id}/eigene-einheiten`, { onSuccess: () => { newUnitOpen.value = false; newUnit.reset() } }) }
function editUnit(unit) { editorUnit.value = unit; unitEditor.defaults({ title: unit.title, notes: unit.notes ?? '' }); unitEditor.title = unit.title; unitEditor.notes = unit.notes ?? '' }
function saveUnit() { unitEditor.put(`/jahresplanung/${props.group.id}/eigene-einheiten/${editorUnit.value.id}`, { onSuccess: () => { editorUnit.value = null } }) }
function addLesson(unit) { useForm({ title: `${unit.title} – neue Stunde`, duration: 1 }).post(`/jahresplanung/${props.group.id}/eigene-einheiten/${unit.id}/stunden`) }
function saveUnitTemplate(unit) { router.post(`/jahresplanung/${props.group.id}/eigene-einheiten/${unit.id}/vorlage`) }
function schedule(lesson, slot = null) { useForm({ schedule_slot_id: slot?.id ?? null }).post(`/jahresplanung/${props.group.id}/lessons/${lesson.id}/einplanen`) }
function scheduleUnit(unit, slot = null) { useForm({ schedule_slot_id: slot?.id ?? null }).post(`/jahresplanung/${props.group.id}/eigene-einheiten/${unit.id}/einplanen`) }
function unscheduleLesson(lesson, moveFollowing = false) { useForm({ move_following: moveFollowing }).delete(`/jahresplanung/${props.group.id}/lessons/${lesson.id}/einplanung`) }
function unscheduleUnit(unit, moveFollowing = false) { useForm({ move_following: moveFollowing }).delete(`/jahresplanung/${props.group.id}/eigene-einheiten/${unit.id}/einplanung`) }
function removeLesson(lesson) { if (window.confirm(de.deleteLessonConfirm)) router.delete(`/jahresplanung/${props.group.id}/lessons/${lesson.id}`) }
function saveLessonTemplate(lesson) { router.post(`/jahresplanung/${props.group.id}/lessons/${lesson.id}/vorlage`) }
function openAutoPlan() { autoPlanForm.schedule_slot_id = autoPlanSlots.value[0]?.id ?? null; autoPlanDialog.value = true }
function submitAutoPlan() { autoPlanForm.post(`/jahresplanung/${props.group.id}/automatisch-einplanen`, { onSuccess: () => { autoPlanDialog.value = false } }) }
function dragScheduledLesson(event, lesson, slot) { if (slot.is_pinned) { event.preventDefault(); return }; draggingScheduledItem.value = true; event.dataTransfer.setData('application/json', JSON.stringify({ source: 'year-plan', type: 'lesson', lesson })) }
function dragScheduledUnit(event, unit, slot) { if (slot.is_pinned) { event.preventDefault(); return }; draggingScheduledItem.value = true; event.dataTransfer.setData('application/json', JSON.stringify({ source: 'year-plan', type: 'unit', unit })) }
function clearSlotPreview() { dragOverSlot.value = null; dropPreviewSlots.value = []; dropInsertSlots.value = []; dropInvalidSlot.value = null; dropOverflow.value = 0 }
function endScheduledDrag() { draggingScheduledItem.value = false; unscheduleDropActive.value = false; clearSlotPreview() }
function hasFollowingContent(item) { const sourceIds = sourceLessonIds(item); const slots = props.workspace.slots; const sourceIndexes = slots.map((slot, index) => slot.scheduled_lesson && sourceIds.includes(slot.scheduled_lesson.lesson_id) ? index : -1).filter(index => index >= 0); const lastSourceIndex = Math.max(...sourceIndexes, -1); return slots.slice(lastSourceIndex + 1).some(slot => slot.scheduled_lesson && !sourceIds.includes(slot.scheduled_lesson.lesson_id)) }
function askRemove(item) { if (hasFollowingContent(item)) { decisionDialog.value = { kind: 'remove', item }; return }; if (item.type === 'unit') unscheduleUnit(item.unit); else unscheduleLesson(item.lesson) }
function dropToRemove(event) { event.stopPropagation(); const item = JSON.parse(event.dataTransfer.getData('application/json')); endScheduledDrag(); if (item.source === 'year-plan') askRemove(item) }
function dragOverUnitsColumn(event) { if (draggingScheduledItem.value) { event.preventDefault(); unscheduleDropActive.value = true; return } dragOverCurriculum(event) }
function dropToRemoveOrTopic(event) { const item = JSON.parse(event.dataTransfer.getData('application/json')); if (item.source === 'year-plan') dropToRemove(event); else dropTopic(event) }
function reorderLessons(unit, sourceId, targetId, insertAfter) { const ids = unit.lessons.map(lesson => lesson.id); const sourceIndex = ids.indexOf(sourceId); if (sourceIndex < 0 || sourceId === targetId) return; ids.splice(sourceIndex, 1); const targetIndex = ids.indexOf(targetId); if (targetIndex < 0) return; ids.splice(insertAfter ? targetIndex + 1 : targetIndex, 0, sourceId); useForm({ lesson_ids: ids }).put(`/jahresplanung/${props.group.id}/eigene-einheiten/${unit.id}/stunden/reihenfolge`) }
function reorderUnits(sourceId, targetId, insertAfter) { const ids = props.workspace.units.map(unit => unit.id); const sourceIndex = ids.indexOf(sourceId); if (sourceIndex < 0 || sourceId === targetId) return; ids.splice(sourceIndex, 1); const targetIndex = ids.indexOf(targetId); if (targetIndex < 0) return; ids.splice(insertAfter ? targetIndex + 1 : targetIndex, 0, sourceId); useForm({ unit_ids: ids }).put(`/jahresplanung/${props.group.id}/eigene-einheiten/reihenfolge`) }
function clearUnitDropPreview() { dragOverUnitId.value = null; dragOverUnitPosition.value = null }
function leaveUnit(event) { if (!event.relatedTarget || !event.currentTarget.contains(event.relatedTarget)) clearUnitDropPreview() }
function dragOverUnit(event, unit) { try { const item = JSON.parse(event.dataTransfer.getData('application/json')); if (item.source === 'units-column' && item.type === 'unit' && item.unit.id !== unit.id) { event.preventDefault(); const bounds = event.currentTarget.getBoundingClientRect(); dragOverUnitId.value = unit.id; dragOverUnitPosition.value = event.clientY > bounds.top + bounds.height / 2 ? 'after' : 'before' } } catch { /* Ignore unrelated drag payloads. */ } }
function dropOnUnit(event, unit) { event.stopPropagation(); try { const item = JSON.parse(event.dataTransfer.getData('application/json')); if (item.source !== 'units-column' || item.type !== 'unit') return; const bounds = event.currentTarget.getBoundingClientRect(); reorderUnits(item.unit.id, unit.id, event.clientY > bounds.top + bounds.height / 2) } catch { /* Ignore unrelated drag payloads. */ } finally { clearUnitDropPreview() } }
function saveSlotStatus(slot, status, reflowMode = null, isPinned = slot.is_pinned) { useForm({ status, label: slot.label, notes: slot.notes, is_pinned: isPinned, ...(reflowMode ? { reflow_mode: reflowMode } : {}) }).put(`/jahresplanung/${props.group.id}/slots/${slot.id}`) }
function selectSlotStatus(slot, status) { slotMenu.value = null; const wasAvailable = ['free', 'buffer'].includes(slot.status); const willBeAvailable = ['free', 'buffer'].includes(status); if (wasAvailable !== willBeAvailable) { const slotIndex = props.workspace.slots.findIndex(candidate => candidate.id === slot.id); const hasFollowing = props.workspace.slots.slice(slotIndex + 1).some(candidate => candidate.scheduled_lesson); if (hasFollowing) { decisionDialog.value = { kind: 'status', slot, status, restoring: !wasAvailable && willBeAvailable }; return }; saveSlotStatus(slot, status, 'remove'); return }; saveSlotStatus(slot, status) }
function togglePinned(slot) { saveSlotStatus(slot, slot.status, null, !slot.is_pinned) }
function resolveDecision(mode) { const decision = decisionDialog.value; decisionDialog.value = null; if (decision.kind === 'insert') { insertAtSlot(decision.item, decision.slot, false, mode === 'move'); return }; if (decision.kind === 'remove') { if (decision.item.type === 'unit') unscheduleUnit(decision.item.unit, mode === 'move'); else unscheduleLesson(decision.item.lesson, mode === 'move'); return }; saveSlotStatus(decision.slot, decision.status, mode) }
const decisionTitle = dialog => dialog.kind === 'insert' ? de.insertReflowQuestion : dialog.kind === 'status' && dialog.restoring ? de.restoreReflowQuestion : dialog.kind === 'status' ? de.reflowQuestion : de.removeFromPlanQuestion
const decisionSecondaryAction = dialog => dialog.kind === 'insert' ? de.keepFree : dialog.kind === 'status' && dialog.restoring ? de.keepSpaceEmpty : dialog.kind === 'status' ? de.removeAffected : de.keepFree
const decisionPrimaryAction = dialog => dialog.kind === 'insert' ? de.moveFollowing : dialog.kind === 'status' && dialog.restoring ? de.moveFollowingIntoSpace : de.moveFollowing
function editLesson(lesson) { editorLesson.value = { ...lesson, unit: props.workspace.units.find(unit => unit.lessons.some(item => item.id === lesson.id)), competency_ids: lesson.competencies?.map(competency => competency.id) ?? [] } }
function saveLesson() {
    const lessonForm = useForm({ title: editorLesson.value.title, duration: editorLesson.value.duration, learning_goals: editorLesson.value.learning_goals, materials: editorLesson.value.materials, homework: editorLesson.value.homework, assessment_note: editorLesson.value.assessment_note, notes: editorLesson.value.notes })
    lessonForm.put(`/jahresplanung/${props.group.id}/lessons/${editorLesson.value.id}`, { onSuccess: () => { useForm({ competency_ids: editorLesson.value.competency_ids ?? [] }).put(`/jahresplanung/${props.group.id}/lessons/${editorLesson.value.id}/kompetenzen`, { onSuccess: () => { editorLesson.value = null } }) } })
}
function readDragItem(event) { try { return JSON.parse(event.dataTransfer.getData('application/json')) } catch { return null } }
function eligiblePlanningSlots() { return props.workspace.slots.filter(slot => slot.status !== 'buffer' && (slot.status === 'free' || slot.scheduled_lesson)) }
function sourceLessonIds(item) { if (item?.type === 'lesson') return [item.lesson?.id]; if (item?.type === 'unit') { const unitId = Number(item.unit?.id); const unit = props.workspace.units.find(candidate => Number(candidate.id) === unitId); const lessons = unit?.lessons ?? []; const lessonIds = lessons.map(lesson => lesson.id); const plannedIds = eligiblePlanningSlots().filter(slot => slot.scheduled_lesson && lessonIds.includes(slot.scheduled_lesson.lesson_id) && !slot.is_pinned).map(slot => slot.scheduled_lesson.lesson_id); return plannedIds.length ? plannedIds : lessons.filter(lesson => lesson.scheduled_lessons?.length).map(lesson => lesson.id) } return [] }
function sourceLength(item) { if (item?.type === 'lesson') return Math.max(1, Number(item.lesson?.duration ?? 1)); return sourceLessonIds(item).reduce((total, id) => total + Math.max(1, Number(props.workspace.units.flatMap(unit => unit.lessons).find(lesson => lesson.id === id)?.duration ?? 1)), 0) }
function canInsert(slot) { return !slot.is_pinned && slot.status !== 'buffer' && (slot.status === 'free' || Boolean(slot.scheduled_lesson)) }
function previewDrop(event, slot) { const item = readDragItem(event); if (!item || !canInsert(slot)) { clearSlotPreview(); return }; const slots = eligiblePlanningSlots(); const targetIndex = slots.findIndex(candidate => candidate.id === slot.id); const length = sourceLength(item); const overflow = estimateDropOverflow(item, slot); dropOverflow.value = overflow; if (targetIndex < 0) { dropInvalidSlot.value = slot.id; dragOverSlot.value = slot.id; return }; const sourceIds = sourceLessonIds(item); const sourceBeforeTarget = slots.findIndex(candidate => candidate.scheduled_lesson && sourceIds.includes(candidate.scheduled_lesson.lesson_id)) < targetIndex; const tail = slots.slice(-length); const hasCapacity = sourceBeforeTarget || tail.every(candidate => !candidate.scheduled_lesson || sourceIds.includes(candidate.scheduled_lesson.lesson_id)); if (!hasCapacity && !overflow && !slots.some(candidate => candidate.is_pinned)) { dropInvalidSlot.value = slot.id; dragOverSlot.value = slot.id; return }; event.preventDefault(); dropInvalidSlot.value = null; dragOverSlot.value = slot.id; dropInsertSlots.value = slots.slice(targetIndex, targetIndex + length).map(candidate => candidate.id); dropPreviewSlots.value = slots.slice(targetIndex).filter(candidate => candidate.scheduled_lesson && !sourceIds.includes(candidate.scheduled_lesson.lesson_id)).map(candidate => candidate.id) }
function insertAtSlot(item, slot, allowOverflow = false, pullFollowing = false) { const sourceId = item.type === 'unit' ? item.unit?.id : item.lesson?.id; if (!sourceId) return; const form = useForm({ type: item.type, source_id: sourceId, allow_overflow: allowOverflow, pull_following: pullFollowing }); form.post(`/jahresplanung/${props.group.id}/slots/${slot.id}/einfügen`, { onSuccess: page => { const serverOverflow = Number(page.props.flash?.planning_overflow ?? 0); if (serverOverflow > 0 && window.confirm(de.dropOverflowConfirm.replace('{count}', String(serverOverflow)))) insertAtSlot(item, slot, true, pullFollowing) } }) }
function alreadyPlanned(item) { return item.type === 'unit' ? (item.unit?.lessons ?? []).some(lesson => (lesson.scheduled_lessons?.length ?? 0) > 0) : (item.lesson?.scheduled_lessons?.length ?? 0) > 0 }
function confirmDuplicateDrop(item) { if (item.source === 'year-plan' || !alreadyPlanned(item)) return true; const title = item.type === 'unit' ? item.unit?.title : item.lesson?.title; const message = (item.type === 'unit' ? de.duplicateUnitConfirm : de.duplicateLessonConfirm).replace('{title}', title ?? ''); return window.confirm(message) }
function estimateDropOverflow(item, slot) { const slots = eligiblePlanningSlots(); const targetIndex = slots.findIndex(candidate => candidate.id === slot.id); const length = sourceLength(item); const sourceIndex = slots.findIndex(candidate => candidate.scheduled_lesson && sourceLessonIds(item).includes(candidate.scheduled_lesson.lesson_id)); if (targetIndex < 0) return 0; const sourceIds = sourceLessonIds(item); const tokens = slots.map(candidate => sourceIds.includes(candidate.scheduled_lesson?.lesson_id) ? null : candidate.scheduled_lesson?.lesson_id); if (sourceIndex >= 0 && sourceIndex < targetIndex) { return Math.max(0, targetIndex + length - tokens.length) } const dropped = tokens.slice(Math.max(targetIndex, tokens.length - length)).filter(Boolean).length; return Math.max(0, targetIndex + length - tokens.length) + dropped }
function confirmDropOverflow(item, slot) { const overflow = estimateDropOverflow(item, slot); if (!overflow) return true; return window.confirm(de.dropOverflowConfirm.replace('{count}', String(overflow))) }
function needsPullFollowing(item, slot) { if (item.source !== 'year-plan' || slot.scheduled_lesson) return false; const sourceIds = sourceLessonIds(item); const slots = eligiblePlanningSlots(); const targetIndex = slots.findIndex(candidate => candidate.id === slot.id); const sourceIndexes = slots.map((candidate, index) => candidate.scheduled_lesson && sourceIds.includes(candidate.scheduled_lesson.lesson_id) ? index : -1).filter(index => index >= 0); const lastSourceIndex = Math.max(...sourceIndexes, -1); return targetIndex >= 0 && lastSourceIndex > targetIndex && slots.slice(lastSourceIndex + 1).some(candidate => candidate.scheduled_lesson && !sourceIds.includes(candidate.scheduled_lesson.lesson_id)) }
function dropOnSlot(event, slot) { const item = readDragItem(event); const overflow = item && (item.type === 'unit' || item.type === 'lesson') ? estimateDropOverflow(item, slot) : 0; clearSlotPreview(); if (!item || !canInsert(slot)) return; if ((item.type === 'unit' || item.type === 'lesson') && confirmDuplicateDrop(item) && confirmDropOverflow(item, slot)) { if (needsPullFollowing(item, slot)) { decisionDialog.value = { kind: 'insert', item, slot }; return }; insertAtSlot(item, slot, overflow > 0) } }
function dragOver(event, slot) { previewDrop(event, slot) }
function leaveSlot(slot) { if (dragOverSlot.value === slot.id) clearSlotPreview() }
function dragLesson(event, lesson) { event.dataTransfer.setData('application/json', JSON.stringify(lesson)) }
function dragPlanningLesson(event, lesson) { event.dataTransfer.setData('application/json', JSON.stringify({ type: 'lesson', lesson })) }
function dragOverLesson(event, unit) { try { const item = JSON.parse(event.dataTransfer.getData('application/json')); if (item.source !== 'year-plan' && item.type === 'lesson' && unit.lessons.some(lesson => lesson.id === item.lesson.id)) { event.preventDefault(); dragOverLessonId.value = event.currentTarget.dataset.lessonId } } catch { /* Ignore unrelated drag payloads. */ } }
function leaveLesson(lesson) { if (dragOverLessonId.value === String(lesson.id)) dragOverLessonId.value = null }
function dropOnLesson(event, unit, targetLesson) { dragOverLessonId.value = null; try { const item = JSON.parse(event.dataTransfer.getData('application/json')); if (item.source === 'year-plan') { dropToRemove(event); return } if (item.type !== 'lesson' || !unit.lessons.some(lesson => lesson.id === item.lesson.id)) return; event.stopPropagation(); const bounds = event.currentTarget.getBoundingClientRect(); reorderLessons(unit, item.lesson.id, targetLesson.id, event.clientY > bounds.top + bounds.height / 2) } catch { /* Ignore unrelated drag payloads. */ } }
function dragUnit(event, unit) { event.dataTransfer.setData('application/json', JSON.stringify({ source: 'units-column', type: 'unit', unit })) }
function dragTopic(event, topic) { event.dataTransfer.setData('application/json', JSON.stringify({ curriculum_topic_id: topic.id })) }
function dragCurriculum(event, topic) { draggingCurriculum.value = true; curriculumDropActive.value = true; dragTopic(event, topic) }
function endCurriculumDrag() { draggingCurriculum.value = false; curriculumDropActive.value = false }
function dragOverCurriculum(event) { if (draggingCurriculum.value) { event.preventDefault(); curriculumDropActive.value = true } }
function dropTopic(event) { endCurriculumDrag(); const value = JSON.parse(event.dataTransfer.getData('application/json')); if (value.curriculum_topic_id) take(curricula.value.find(topic => topic.id === value.curriculum_topic_id)) }
</script>

<template>
    <AppShell>
        <template #toolbar>
            <a href="/jahresplanung" class="btn btn-sm btn-light" :title="de.close" :aria-label="de.close"><i class="bi bi-x-lg" aria-hidden="true"></i></a>
            <button class="btn btn-sm btn-outline-secondary" type="button" :title="de.undoReflow" :aria-label="de.undoReflow" :disabled="!canUndoReflow" @click="router.post(`/jahresplanung/${group.id}/reflow/rueckgaengig`)"><i class="bi bi-arrow-counterclockwise" aria-hidden="true"></i></button>
            <label class="visually-hidden" for="active-group">{{ de.activeTeachingGroup }}</label>
            <select id="active-group" class="form-select form-select-sm" :aria-label="de.activeTeachingGroup" :value="group.id" @change="router.visit(`/jahresplanung/${$event.target.value}`)"><option v-for="option in groupOptions" :key="option.id" :value="option.id">{{ option.name }} · {{ option.school_year.name }}</option></select>
            <span class="small text-muted d-none d-md-inline">{{ group.school_year.name }}</span>
        </template>
        <div class="container-fluid px-3 py-4 year-planning-page">
            <h1 class="h2">{{ de.yearPlans }}</h1>
            <div v-if="$page.props.flash?.success" class="alert alert-success" role="status">{{ $page.props.flash.success }}</div>
            <div v-if="$page.props.flash?.warning" class="alert alert-warning" role="alert">{{ $page.props.flash.warning }}</div>
            <div class="small text-muted mb-3">{{ group.school.name }} · {{ group.school_year.name }} · {{ de.coverage }}: {{ coveragePercent }} % · {{ workspace.coverage.education_plan_lesson }} {{ de.competenciesInLessons }}</div>
            <div class="year-planning-grid" :class="{ 'curriculum-collapsed': !curriculumOpen }">
                <section class="planning-column planning-year" aria-labelledby="year-plan-heading">
                    <div class="d-flex justify-content-between align-items-center mb-2"><h2 id="year-plan-heading" class="h5 mb-0">{{ de.yearPlanColumn }}</h2><span class="badge text-bg-light">{{ workspace.slots.length }}</span></div><p class="small text-muted">{{ de.yearPlanQuestion }}</p>
                    <template v-for="entry in planningEntries" :key="`${entry.type}-${entry.date}-${entry.holiday?.id ?? ''}`">
                        <div v-if="entry.type === 'holiday'" class="holiday-divider"><i class="bi bi-sun me-1" aria-hidden="true"></i><strong>{{ entry.holiday.name || de.holidays }}</strong><span class="small ms-2">{{ formatDate(entry.holiday.starts_on) }} – {{ formatDate(entry.holiday.ends_on) }}</span></div>
                        <div v-else class="planning-day"><h3 class="h6 mb-2">{{ formatDate(entry.date) }}</h3><div v-for="slot in entry.slots" :key="slot.id" class="planning-slot" :class="[unitTone(slot.scheduled_lesson?.lesson?.unit), { 'slot-blocked': slot.status !== 'free' && slot.status !== 'buffer', 'drop-ready': dragOverSlot === slot.id, 'drop-preview': dropPreviewSlots.includes(slot.id), 'drop-insert': dropInsertSlots.includes(slot.id), 'drop-invalid': dropInvalidSlot === slot.id }]" @dragover="dragOver($event, slot)" @dragleave="leaveSlot(slot)" @drop="dropOnSlot($event, slot)"><div class="d-flex align-items-center gap-2"><span class="small text-muted">{{ slot.period_number }}. {{ de.period }}</span><template v-if="slot.scheduled_lesson"><span class="drag-handle" draggable="true" :title="de.dragScheduledUnit" :aria-label="de.dragScheduledUnit" @dragstart="dragScheduledUnit($event, slot.scheduled_lesson.lesson.unit, slot)" @dragend="endScheduledDrag"><i class="bi bi-grip-vertical" aria-hidden="true"></i></span><span class="drag-handle" draggable="true" :title="de.dragScheduledLesson" :aria-label="de.dragScheduledLesson" @dragstart="dragScheduledLesson($event, slot.scheduled_lesson.lesson, slot)" @dragend="endScheduledDrag"><i class="bi bi-grip-horizontal" aria-hidden="true"></i></span></template><div class="flex-grow-1 planning-slot-label"><div>{{ slot.scheduled_lesson?.lesson?.title || de.available }}</div><div v-if="slot.scheduled_lesson" class="small text-muted">{{ slot.scheduled_lesson.lesson.unit.title }}</div></div><div class="dropdown"><button v-if="slot.scheduled_lesson" class="btn btn-sm btn-link p-0" type="button" :title="slot.is_pinned ? de.unpinSlot : de.pinSlot" :aria-label="slot.is_pinned ? de.unpinSlot : de.pinSlot" @click.stop="togglePinned(slot)"><i :class="slot.is_pinned ? 'bi bi-pin-angle-fill' : 'bi bi-pin-angle'" aria-hidden="true"></i></button><button class="btn btn-sm btn-link p-0" type="button" :title="de.changeSlotStatus" :aria-label="de.changeSlotStatus" :aria-expanded="slotMenu === slot.id" @click.stop="slotMenu = slotMenu === slot.id ? null : slot.id"><span class="badge" :class="statusClass(slot)">{{ statusLabel(slot) }}</span></button><div v-if="slotMenu === slot.id" class="dropdown-menu show dropdown-menu-end p-1"><button v-for="option in slotStatusOptions" :key="option.value" class="dropdown-item rounded small" type="button" @click="selectSlotStatus(slot, option.value)">{{ option.label }}</button></div></div></div></div></div>
                    </template>
                    <div v-if="!planningEntries.length" class="text-muted small">{{ de.noScheduleSlots }}</div>
                </section>
                <section class="planning-column planning-units" :class="{ 'curriculum-drop-ready': curriculumDropActive, 'unschedule-column-ready': draggingScheduledItem }" aria-labelledby="units-heading" @dragover="dragOverUnitsColumn" @dragleave="curriculumDropActive = false; unscheduleDropActive = false" @drop="dropToRemoveOrTopic">
                    <div class="d-flex justify-content-between align-items-center mb-2"><h2 id="units-heading" class="h5 mb-0">{{ de.myTeachingUnits }}</h2><div class="d-flex gap-1"><button class="btn btn-sm btn-outline-primary" type="button" :title="de.autoPlan" :aria-label="de.autoPlan" @click="openAutoPlan"><i class="bi bi-magic me-1" aria-hidden="true"></i>{{ de.autoPlan }}</button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.addUnit" :aria-label="de.addUnit" @click="newUnitOpen = true"><i class="bi bi-plus-lg" aria-hidden="true"></i></button></div></div><p class="small text-muted">{{ de.myUnitsQuestion }}</p><div v-if="draggingScheduledItem" class="unschedule-drop-zone" :class="{ 'drop-ready': unscheduleDropActive }" @dragover.prevent="unscheduleDropActive = true" @dragleave="unscheduleDropActive = false" @drop="dropToRemove"><i class="bi bi-trash3 me-1" aria-hidden="true"></i>{{ de.removeFromPlanDropHint }}</div>
                    <div v-if="!workspace.units.length" class="text-muted small">{{ de.noTeachingUnits }}</div>
                    <article v-for="unit in workspace.units" :key="unit.id" class="card mb-2 planning-card" :class="[unitTone(unit), `plan-state-${unitPlanState(unit)}`, { 'drop-ready': dragOverUnitId === unit.id, 'unit-drop-before': dragOverUnitId === unit.id && dragOverUnitPosition === 'before', 'unit-drop-after': dragOverUnitId === unit.id && dragOverUnitPosition === 'after' }]" @dragover="dragOverUnit($event, unit)" @dragleave="leaveUnit($event)" @drop="dropOnUnit($event, unit)"><div class="card-body p-3"><div class="d-flex align-items-start gap-2"><span class="drag-handle" draggable="true" :title="de.dragUnit" :aria-label="de.dragUnit" @dragstart="dragUnit($event, unit)" @dragend="clearUnitDropPreview"><i class="bi bi-grip-vertical" aria-hidden="true"></i></span><button class="btn btn-sm btn-link p-0" type="button" :aria-expanded="isExpanded(unit)" @click="toggleUnit(unit)"><i :class="isExpanded(unit) ? 'bi bi-chevron-down' : 'bi bi-chevron-right'" aria-hidden="true"></i><span class="visually-hidden">{{ de.expandUnit }}</span></button><div class="flex-grow-1"><strong>{{ unit.title }}</strong><div class="small text-muted">{{ unit.source_curriculum_topic ? `${de.sourceCurriculum}: ${unit.source_curriculum_topic.title}` : de.ownUnit }} · {{ unit.lessons.length }} {{ de.lessons }}</div></div><div class="d-flex align-items-center gap-1"><span class="badge plan-state-badge" :class="`plan-state-${unitPlanState(unit)}`" :title="planStateLabel(unitPlanState(unit))"><i :class="unitPlanState(unit) === 'planned' ? 'bi bi-check-circle' : unitPlanState(unit) === 'partial' ? 'bi bi-circle-half' : 'bi bi-circle'" aria-hidden="true"></i><span class="visually-hidden">{{ planStateLabel(unitPlanState(unit)) }}</span></span><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.editUnit" :aria-label="de.editUnit" @click="editUnit(unit)"><i class="bi bi-pencil-square" aria-hidden="true"></i></button><button class="btn btn-sm btn-outline-primary" type="button" :title="de.addLesson" :aria-label="de.addLesson" @click="addLesson(unit)"><i class="bi bi-plus-lg" aria-hidden="true"></i></button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.saveAsUnitTemplate" :aria-label="de.saveAsUnitTemplate" @click="saveUnitTemplate(unit)"><i class="bi bi-bookmark-plus" aria-hidden="true"></i></button></div></div><div v-if="isExpanded(unit)" class="mt-3 ps-3"><div v-if="!unit.lessons.length" class="small text-muted">{{ de.noLessons }}</div><div v-for="lesson in unit.lessons" :key="lesson.id" class="lesson-row" :class="{ 'drop-ready': dragOverLessonId === String(lesson.id) }" :data-lesson-id="lesson.id" @dragover="dragOverLesson($event, unit)" @dragleave="leaveLesson(lesson)" @drop="dropOnLesson($event, unit, lesson)"><div class="d-flex align-items-center gap-2"><span class="drag-handle" draggable="true" :title="de.dragLesson" :aria-label="de.dragLesson" @dragstart="dragPlanningLesson($event, lesson)" @dragend="dragOverLessonId = null"><i class="bi bi-grip-vertical" aria-hidden="true"></i></span><span class="flex-grow-1"><strong>{{ lesson.title }}</strong><span class="small text-muted ms-2">{{ lesson.duration }} {{ de.hours.toLowerCase() }}</span></span><span class="badge plan-state-badge" :class="lessonIsPlanned(lesson) ? 'plan-state-planned' : 'plan-state-not-planned'" :title="lessonIsPlanned(lesson) ? de.planned : de.notPlanned"><i :class="lessonIsPlanned(lesson) ? 'bi bi-check-circle' : 'bi bi-circle'" aria-hidden="true"></i><span class="visually-hidden">{{ lessonIsPlanned(lesson) ? de.planned : de.notPlanned }}</span></span><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.editLesson" :aria-label="de.editLesson" @click="editLesson(lesson)"><i class="bi bi-pencil-square" aria-hidden="true"></i><span class="visually-hidden">{{ de.editLesson }}</span></button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.saveAsLessonTemplate" :aria-label="de.saveAsLessonTemplate" @click="saveLessonTemplate(lesson)"><i class="bi bi-bookmark-plus" aria-hidden="true"></i></button><button class="btn btn-sm btn-outline-danger" type="button" :title="de.removeLesson" :aria-label="de.removeLesson" @click="removeLesson(lesson)"><i class="bi bi-trash" aria-hidden="true"></i></button></div><div class="small text-muted">{{ lesson.scheduled_lessons?.length ?? 0 }}/{{ lesson.duration }} {{ de.slotsPlanned }}</div></div></div></div></article>
                </section>
                <section v-if="curriculumOpen" class="planning-column planning-curricula" aria-labelledby="curricula-heading"><div class="d-flex justify-content-between align-items-center mb-2"><h2 id="curricula-heading" class="h5 mb-0">{{ workspace.curricula.length === 1 ? de.curriculum : de.curricula }}</h2><button class="btn btn-sm btn-outline-secondary" type="button" :aria-label="de.collapseCurriculum" :title="de.collapseCurriculum" @click="curriculumOpen = false"><i class="bi bi-layout-sidebar-inset-reverse" aria-hidden="true"></i></button></div><p class="small text-muted">{{ de.curriculumQuestion }}</p><div v-for="topic in curricula" :key="topic.id" class="card mb-2 planning-card"><div class="card-body p-3"><span class="drag-handle" draggable="true" :title="de.dragCurriculum" :aria-label="de.dragCurriculum" @dragstart="dragCurriculum($event, topic)" @dragend="endCurriculumDrag"><i class="bi bi-grip-vertical" aria-hidden="true"></i></span><strong>{{ topic.title }}</strong><div class="small text-muted">{{ topic.curriculum_title }} · {{ topic.hours || 1 }} {{ de.hours.toLowerCase() }} · {{ topic.competencies.length }} {{ de.competencies }}</div><details class="mt-2"><summary class="small">{{ de.showCompetencies }}</summary><ul class="small mb-0 ps-3"><li v-for="competency in topic.competencies" :key="competency.id">{{ competencyText(competency) }}</li></ul></details></div></div></section>
                <button v-else class="btn btn-sm btn-outline-secondary curriculum-open-button" type="button" @click="curriculumOpen = true">{{ de.showCurricula }}</button>
            </div>
        </div>
        <div v-if="newUnitOpen" class="roo-modal-backdrop" role="presentation" @click.self="newUnitOpen = false"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.addUnit"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ de.addUnit }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="newUnitOpen = false"></button></div><form @submit.prevent="createUnit"><label class="form-label" for="new-unit-title">{{ de.unitTitle }}</label><input id="new-unit-title" v-model="newUnit.title" class="form-control" required><label class="form-label mt-2" for="new-unit-notes">{{ de.notes }}</label><textarea id="new-unit-notes" v-model="newUnit.notes" class="form-control" rows="3"></textarea><div class="d-flex justify-content-end gap-2 mt-4"><button class="btn btn-outline-secondary" type="button" @click="newUnitOpen = false">{{ de.cancel }}</button><button class="btn btn-primary" type="submit">{{ de.save }}</button></div></form></div></div></section></div>
        <div v-if="editorUnit" class="roo-modal-backdrop" role="presentation" @click.self="editorUnit = null"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.editUnit"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ de.editUnit }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="editorUnit = null"></button></div><form @submit.prevent="saveUnit"><label class="form-label" for="edit-unit-title">{{ de.unitTitle }}</label><input id="edit-unit-title" v-model="unitEditor.title" class="form-control" required><label class="form-label mt-2" for="edit-unit-notes">{{ de.notes }}</label><textarea id="edit-unit-notes" v-model="unitEditor.notes" class="form-control" rows="4"></textarea><div class="d-flex justify-content-end gap-2 mt-4"><button class="btn btn-outline-secondary" type="button" @click="editorUnit = null">{{ de.cancel }}</button><button class="btn btn-primary" type="submit" :disabled="unitEditor.processing">{{ de.saveChanges }}</button></div></form></div></div></section></div>
        <div v-if="editorLesson" class="roo-modal-backdrop" role="presentation" @click.self="editorLesson = null"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.editLesson"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ de.editLesson }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="editorLesson = null"></button></div><label class="form-label">{{ de.lessonTitle }}</label><input v-model="editorLesson.title" class="form-control"><label class="form-label mt-2">{{ de.lessonDuration }}</label><input v-model="editorLesson.duration" type="number" min="1" class="form-control"><label class="form-label mt-2">{{ de.learningGoals }}</label><textarea v-model="editorLesson.learning_goals" class="form-control" rows="3"></textarea><label class="form-label mt-2">{{ de.materials }}</label><textarea v-model="editorLesson.materials" class="form-control" rows="3"></textarea><div v-if="editorLesson.unit?.competencies?.length" class="mt-3"><span class="form-label d-block">{{ de.competencies }}</span><label v-for="competency in editorLesson.unit.competencies" :key="competency.id" class="form-check"><input v-model="editorLesson.competency_ids" class="form-check-input" type="checkbox" :value="competency.id"><span class="form-check-label small">{{ competencyText(competency) }}</span></label></div><div class="d-flex justify-content-end gap-2 mt-4"><button class="btn btn-outline-secondary" type="button" @click="editorLesson = null">{{ de.cancel }}</button><button class="btn btn-primary" type="button" @click="saveLesson">{{ de.saveChanges }}</button></div><hr><h3 class="h6">{{ de.phases }}</h3><button v-for="phase in editorLesson.phases" :key="phase.id" class="btn btn-sm btn-outline-secondary me-1" type="button" @click="phaseEditor = phase">{{ phase.title }}</button></div></div></section></div>
        <aside v-if="phaseEditor" class="offcanvas offcanvas-end show" tabindex="-1" aria-modal="true" role="dialog"><div class="offcanvas-header"><h2 class="h5 mb-0">{{ de.phaseEditor }}</h2><button type="button" class="btn-close" :aria-label="de.close" @click="phaseEditor = null"></button></div><div class="offcanvas-body"><form @submit.prevent="useForm(phaseEditor).put(`/jahresplanung/${group.id}/phasen/${phaseEditor.id}`, { onSuccess: () => { phaseEditor = null } })"><label class="form-label">{{ de.phaseTitle }}</label><input v-model="phaseEditor.title" class="form-control"><label class="form-label mt-2">{{ de.description }}</label><textarea v-model="phaseEditor.description" class="form-control" rows="5"></textarea><button class="btn btn-primary mt-3" type="submit">{{ de.saveChanges }}</button></form></div></aside>
<div v-if="autoPlanDialog" class="roo-modal-backdrop" role="presentation" @click.self="autoPlanDialog = false"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.autoPlanTitle"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ de.autoPlanTitle }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="autoPlanDialog = false"></button></div><fieldset class="mb-3"><legend class="h6">{{ de.autoPlanStart }}</legend><label class="form-check"><input v-model="autoPlanForm.start_mode" class="form-check-input" type="radio" value="free"><span class="form-check-label">{{ de.autoPlanFreeStart }}</span></label><label class="form-check"><input v-model="autoPlanForm.start_mode" class="form-check-input" type="radio" value="end"><span class="form-check-label">{{ de.autoPlanEndStart }}</span></label></fieldset><div v-if="autoPlanForm.start_mode === 'free'" class="mb-3"><label class="form-label">{{ de.autoPlanChooseSlot }}</label><select v-model="autoPlanForm.schedule_slot_id" class="form-select"><option v-for="slot in autoPlanSlots" :key="slot.id" :value="slot.id">{{ formatDate(slot.date) }} · {{ slot.period_number }}. {{ de.period }}</option></select></div><div class="form-check mb-3"><input id="auto-plan-together" v-model="autoPlanForm.keep_together" class="form-check-input" type="checkbox"><label class="form-check-label" for="auto-plan-together">{{ de.autoPlanKeepTogether }}</label><div class="form-text">{{ autoPlanForm.keep_together ? de.autoPlanKeepTogetherHint : de.autoPlanLooseHint }}</div></div><div class="d-flex justify-content-end gap-2"><button class="btn btn-outline-secondary" type="button" @click="autoPlanDialog = false">{{ de.cancel }}</button><button class="btn btn-primary" type="button" :disabled="autoPlanForm.processing || (autoPlanForm.start_mode === 'free' && !autoPlanForm.schedule_slot_id)" @click="submitAutoPlan">{{ de.autoPlan }}</button></div></div></div></section></div>
        <div v-if="decisionDialog" class="roo-modal-backdrop" role="presentation" @click.self="decisionDialog = null"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="decisionTitle(decisionDialog)"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ decisionTitle(decisionDialog) }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="decisionDialog = null"></button></div><p class="text-muted">{{ decisionTitle(decisionDialog) }}</p><div class="d-flex flex-wrap justify-content-end gap-2"><button class="btn btn-outline-secondary" type="button" @click="resolveDecision(decisionDialog.kind === 'status' ? 'remove' : 'keep')">{{ decisionSecondaryAction(decisionDialog) }}</button><button class="btn btn-primary" type="button" @click="resolveDecision('move')">{{ decisionPrimaryAction(decisionDialog) }}</button></div></div></div></section></div>
    </AppShell>
</template>
